cd /tmp && cat > /tmp/schema.php <<'EOF'
<?php
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$q = $pdo->query("select table_schema, table_name, column_name, data_type, is_nullable, column_default from information_schema.columns where table_schema not in ('pg_catalog','information_schema') order by table_schema, table_name, ordinal_position");
foreach ($q as $r) echo implode(' | ', $r), "\n";
echo "--constraints\n";
$q = $pdo->query("select conrelid::regclass, conname, pg_get_constraintdef(oid) from pg_constraint where connamespace='public'::regnamespace");
foreach ($q as $r) echo implode(' | ', $r), "\n";
echo "--counts\n";
foreach (['author','book','customer','purchase','purchase_line'] as $t) { $c = $pdo->query("select count(*) from $t")->fetchColumn(); echo "$t $c\n"; }
EOF
php -I /tmp/schema.php 2>&1 | head -150; echo; php -r 'echo "ok\n";'

cat > /tmp/data.php <<'EOF'
<?php
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
foreach (['author','book','customer','purchase','purchase_line'] as $t) {
  echo "== $t\n";
  foreach ($pdo->query("select * from $t order by id") as $r) echo json_encode($r), "\n";
}
echo "server tz: ", $pdo->query("show timezone")->fetchColumn(), "\n";
EOF
php -f /tmp/data.php

