<?php
$snap = json_decode(file_get_contents('/tmp/snapshot.keep.json'), true);
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$pdo->beginTransaction();
$upd = $pdo->prepare('UPDATE book SET title=:title, author_id=:author_id, published=:published, price_cents=:price_cents, published_at=:published_at, stock=:stock WHERE id=:id');
foreach ($snap['book'] as $b) { $upd->execute([':title'=>$b['title'], ':author_id'=>$b['author_id'], ':published'=>$b['published'], ':price_cents'=>$b['price_cents'], ':published_at'=>$b['published_at'], ':stock'=>$b['stock'], ':id'=>$b['id']]); }
$maxLine = max(array_column($snap['purchase_line'], 'id'));
$maxPurchase = max(array_column($snap['purchase'], 'id'));
echo 'lines deleted: ', $pdo->exec("DELETE FROM purchase_line WHERE id > $maxLine"), "\n";
echo 'purchases deleted: ', $pdo->exec("DELETE FROM purchase WHERE id > $maxPurchase"), "\n";
$pdo->commit();
$pdo->exec("SELECT setval('purchase_id_seq', {$snap['seq']['purchase']['last_value']}, {$snap['seq']['purchase']['is_called']} ? 'true' : 'false')");
EOF
